test("blocked CI recovery preserves a dirty historical worktree and uses a detached recovery worktree",()=>{const x=blockedRecovery("agent_loop","payload\n"),historical=x.r.worktree,forensic=join(historical,"forensic.txt");writeFileSync(forensic,"preserve me\n");const historicalHead=execFileSync("git",["-C",historical,"rev-parse","HEAD"],{encoding:"utf8"}).trim(),historicalStatus=execFileSync("git",["-C",historical,"status","--porcelain","--untracked-files=all"],{encoding:"utf8"});const head=new GovernedBuilder(x.r.source,x.r.worktrees,x.bus,()=>{},"must-not-run").synchronizeBlockedCiBase(x.nextSpec,x.state),recovery=join(x.r.worktrees,`${spec.front_id}-blocked-ci-recovery-${x.oldHead.slice(0,12)}`);assert.equal(execFileSync("git",["-C",historical,"rev-parse","HEAD"],{encoding:"utf8"}).trim(),historicalHead);assert.equal(execFileSync("git",["-C",historical,"status","--porcelain","--untracked-files=all"],{encoding:"utf8"}),historicalStatus);assert.equal(readFileSync(forensic,"utf8"),"preserve me\n");assert.equal(execFileSync("git",["-C",recovery,"branch","--show-current"],{encoding:"utf8"}).trim(),"");assert.equal(execFileSync("git",["-C",recovery,"rev-parse","HEAD"],{encoding:"utf8"}).trim(),head);assert.equal(execFileSync("git",["-C",recovery,"status","--porcelain","--untracked-files=all"],{encoding:"utf8"}).trim(),"");assert.equal(x.remoteHead(),head);});

test("blocked CI recovery fails closed when its deterministic recovery worktree is dirty",()=>{const x=blockedRecovery("agent_loop","payload\n"),historical=x.r.worktree,forensic=join(historical,"forensic.txt");writeFileSync(forensic,"historical evidence\n");const recovery=join(x.r.worktrees,`${spec.front_id}-blocked-ci-recovery-${x.oldHead.slice(0,12)}`);execFileSync("git",["-C",x.r.source,"worktree","add","--detach",recovery,x.oldHead]);writeFileSync(join(recovery,"unexpected.txt"),"deny\n");const historicalStatus=execFileSync("git",["-C",historical,"status","--porcelain","--untracked-files=all"],{encoding:"utf8"});assert.throws(()=>new GovernedBuilder(x.r.source,x.r.worktrees,x.bus,()=>{},"must-not-run").synchronizeBlockedCiBase(x.nextSpec,x.state),/blocked CI recovery worktree state invalid/);assert.equal(x.remoteHead(),x.oldHead);assert.equal(execFileSync("git",["-C",historical,"status","--porcelain","--untracked-files=all"],{encoding:"utf8"}),historicalStatus);assert.equal(readFileSync(forensic,"utf8"),"historical evidence\n");});

test("validated unpublished repair survives consecutive base advances without a model rerun",async()=>{const x=blockedRecovery("codex_control_plane","before\n");writeFileSync(join(x.r.worktree,"docs","x.md"),"after\n");execFileSync("git",["-C",x.r.worktree,"add","docs/x.md"]);execFileSync("git",["-C",x.r.worktree,"commit","-m",`feat(control-plane): complete ${spec.front_id}\n\nBUILDER_BACKEND=opencode_ollama\nBUILDER_MODEL=ollama-cloud/deepseek-v4-pro\nPROVIDER_SESSION=deepseek-repair`]);const candidate=execFileSync("git",["-C",x.r.worktree,"rev-parse","HEAD"],{encoding:"utf8"}).trim(),builder=new GovernedBuilder(x.r.source,x.r.worktrees,x.bus,()=>{},"must-not-run"),first=builder.synchronizeBlockedCiBase(x.nextSpec,x.state);assert.deepEqual(execFileSync("git",["-C",x.r.worktree,"rev-list","--parents","-n","1",first],{encoding:"utf8"}).trim().split(/\s+/),[first,candidate,x.nextBase]);writeFileSync(join(x.r.source,"BASE3.md"),"base3\n");execFileSync("git",["-C",x.r.source,"add","BASE3.md"]);execFileSync("git",["-C",x.r.source,"commit","-m","base 3"]);const base3=execFileSync("git",["-C",x.r.source,"rev-parse","HEAD"],{encoding:"utf8"}).trim();execFileSync("git",["-C",x.r.source,"push","origin",`HEAD:refs/heads/codex/own-capital-sustainable-return`]);const identity=x.bus.prIdentity;x.bus.prIdentity=()=>({...identity(),baseRefOid:x.nextBase});const finalSpec={...x.nextSpec,expected_base_sha:base3},synced=builder.synchronizeBlockedCiBase(finalSpec,{...x.state,base_sha:x.nextBase,head_sha:first});assert.deepEqual(execFileSync("git",["-C",x.r.worktree,"rev-list","--parents","-n","1",synced],{encoding:"utf8"}).trim().split(/\s+/),[synced,first,base3]);x.bus.findPrByBranch=()=>({number:91,head_sha:synced});x.bus.prIdentity=()=>({...identity(),baseRefOid:base3,headRefOid:synced});x.bus.repairPrompt=()=>"must not execute";x.bus.bindPrToIssue=()=>{};let executions=0;const result=await new GovernedBuilder(x.r.source,x.r.worktrees,x.bus,effect=>{if(effect==="builder_execute")executions++;},"must-not-run").build(finalSpec,90,"recovered-session",1);assert.deepEqual(result,{pr:91,head_sha:synced,session:"recovered-session",recovered_repair:true});assert.equal(executions,0);});
test("recovered repair rejects a synchronization subject without two parents",async()=>{const {r,head}=publishedCandidate();execFileSync("git",["-C",r.worktree,"commit","--allow-empty","-m",`chore(control-plane): synchronize ${spec.front_id} base`]);const falseSync=execFileSync("git",["-C",r.worktree,"rev-parse","HEAD"],{encoding:"utf8"}).trim();execFileSync("git",["-C",r.worktree,"push","origin",`HEAD:refs/heads/${spec.work_branch}`]);let bound=0;const bus:any={findPrByBranch:()=>({number:93,head_sha:falseSync}),remoteBranchHead:()=>falseSync,prIdentity:()=>({author:{login:"cesarmanuel8102"},baseRefName:"codex/own-capital-sustainable-return",baseRefOid:r.base,headRefName:spec.work_branch,headRefOid:falseSync,headRepository:{nameWithOwner:"cesarmanuel8102/AI_Vault"},isCrossRepository:false,isDraft:true,state:"OPEN",files:[{path:"docs/x.md"}]}),bindPrToIssue:()=>{bound++;},repairPrompt:()=>""};await assert.rejects(new GovernedBuilder(r.source,r.worktrees,bus,()=>{},"must-not-run").build({...spec,expected_base_sha:r.base},90,"false-sync",1),/synchronization invalid/);assert.equal(bound,0);assert.notEqual(falseSync,head);});

test("unattested synchronized repair falls through to a fresh governed rebuild",async()=>{const {r,head}=publishedCandidate(false),tree=execFileSync("git",["-C",r.worktree,"rev-parse",`${head}^{tree}`],{encoding:"utf8"}).trim(),sync=execFileSync("git",["-C",r.worktree,"commit-tree",tree,"-p",head,"-p",r.base,"-m",`chore(control-plane): synchronize ${spec.front_id} base`],{encoding:"utf8"}).trim();execFileSync("git",["-C",r.worktree,"merge","--ff-only",sync]);execFileSync("git",["-C",r.worktree,"push","origin",`HEAD:refs/heads/${spec.work_branch}`]);let bound=0,executions=0;const bus:any={findPrByBranch:()=>({number:93,head_sha:sync}),remoteBranchHead:()=>execFileSync("git",["--git-dir",r.remote,"rev-parse",`refs/heads/${spec.work_branch}`],{encoding:"utf8"}).trim(),prIdentity:()=>({author:{login:"cesarmanuel8102"},baseRefName:"codex/own-capital-sustainable-return",baseRefOid:r.base,headRefName:spec.work_branch,headRefOid:sync,headRepository:{nameWithOwner:"cesarmanuel8102/AI_Vault"},isCrossRepository:false,isDraft:true,state:"OPEN",files:[{path:"docs/x.md"}]}),bindPrToIssue:()=>{bound++;},repairPrompt:()=>"produce the required provenance receipt"};const entry=join(r.source,"fake-codex.js"),prior=process.env.CODEX_ENTRYPOINT,priorRoot=process.env.OPERATOR_PROXY_ROOT;writeFileSync(entry,fakeCodexScript("fresh receipt rebuild"));process.env.CODEX_ENTRYPOINT=entry;process.env.OPERATOR_PROXY_ROOT=r.root;try{const result=await new GovernedBuilder(r.source,r.worktrees,bus,effect=>{if(effect==="builder_execute")executions++;},process.execPath).build({...spec,expected_base_sha:r.base},90,"sync-receipt-repair",1);assert.notEqual(result.head_sha,sync);assert.equal(bound,1);assert.equal(executions,1);assert.match(execFileSync("git",["-C",r.worktree,"show","-s","--format=%B",result.head_sha],{encoding:"utf8"}),/BUILDER_BACKEND=codex_cli_openai/);}finally{if(prior===undefined)delete process.env.CODEX_ENTRYPOINT;else process.env.CODEX_ENTRYPOINT=prior;if(priorRoot===undefined)delete process.env.OPERATOR_PROXY_ROOT;else process.env.OPERATOR_PROXY_ROOT=priorRoot;}});
test("blocked CI synchronization rejects non-pending mergeability",()=>{const x=blockedRecovery("codex_control_plane","payload\n"),original=x.bus.prIdentity;x.bus.prIdentity=()=>({...original(),mergeable:"CONFLICTING"});assert.throws(()=>new GovernedBuilder(x.r.source,x.r.worktrees,x.bus,()=>{},"must-not-run").synchronizeBlockedCiBase(x.nextSpec,x.state),/PR identity invalid/);assert.equal(x.remoteHead(),x.oldHead);});
